#!/bin/sh
# Makes compiler/src/arch/tables.vl from the intrinsic tables (0.19):
# portable.def, aarch64.def and x86_64.def (the intrinsics, each section
# after a line `= ARCH`), and insn_a64.def and insn_x86.def (the
# instructions' encodings), as functions writing their lines to a buffer,
# comments and blank lines left out. compiler/src/arch/table.vl parses
# them on a program's first use of std::arch. compiler/arch/README.md gives
# the formats. Run it after changing a .def file; tests/run.sh checks that
# the generated file agrees.
#
# usage: compiler/arch/embed.sh [-c]   (-c: only check, exit 1 if stale)
set -eu
cd "$(dirname "$0")/../.."
out=compiler/src/arch/tables.vl
tmp=$(mktemp "$out.XXXXXX")
# The lines of a .def file on stdin, without comments and blank lines, as
# statements writing them (string literals cannot span lines).
lines() {
    grep -v '^[[:space:]]*#' | grep -v '^[[:space:]]*$' \
        | sed -e 's/\\/\\\\/g' -e 's/"/\\"/g' -e 's/^/        buf_str(out, c"/' -e 's/$/\\n");/'
}
{
    echo "// Generated by compiler/arch/embed.sh from compiler/arch/*.def (do not"
    echo "// edit): the intrinsic tables (0.19), parsed by arch/table.vl on a"
    echo "// program's first use of std::arch."
    echo ""
    echo "use crate::base::buf_str;"
    echo ""
    echo "// The intrinsics: portable.def, aarch64.def, x86_64.def, each after a"
    echo "// line \`= ARCH\`."
    echo "pub fn intrinsics_source(out: i64) {"
    echo "    unsafe {"
    for a in portable aarch64 x86_64; do
        printf '        buf_str(out, c"= %s\\n");\n' "$a"
        lines <"compiler/arch/$a.def"
    done
    echo "    }"
    echo "}"
    echo ""
    echo "// The AArch64 instructions' encodings: insn_a64.def."
    echo "pub fn insn_a64_source(out: i64) {"
    echo "    unsafe {"
    lines <compiler/arch/insn_a64.def
    echo "    }"
    echo "}"
    echo ""
    echo "// The x86-64 instructions' encodings: insn_x86.def."
    echo "pub fn insn_x86_source(out: i64) {"
    echo "    unsafe {"
    lines <compiler/arch/insn_x86.def
    echo "    }"
    echo "}"
} >"$tmp"
if [ "${1:-}" = "-c" ]; then
    if cmp -s "$tmp" "$out"; then rm -f "$tmp"; exit 0; fi
    rm -f "$tmp"
    echo "$out is stale: run compiler/arch/embed.sh" >&2
    exit 1
fi
mv "$tmp" "$out"
